"use client";

import { useEffect, useState } from "react";
import dynamic from "next/dynamic";
import { ContinuityLabProvider } from "@/components/continuity-lab/continuity-lab-context";
import { resolveActiveEpochWorkspaceId } from "@/lib/epoch-api";

const MissionControlWorkspace = dynamic(
  () =>
    import("@/components/mission-control/mission-control-workspace").then(
      (mod) => mod.MissionControlWorkspace,
    ),
  {
    ssr: false,
    loading: () => (
      <div className="flex min-h-screen items-center justify-center bg-white text-[14px] text-[#555]">
        Loading Mission Control...
      </div>
    ),
  },
);

export function MissionControlClient() {
  const [workspaceReady, setWorkspaceReady] = useState(false);
  const [workspaceError, setWorkspaceError] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;

    const bootstrapWorkspace = async () => {
      try {
        const workspaceId = await resolveActiveEpochWorkspaceId();
        if (!workspaceId && !cancelled) {
          setWorkspaceError("Unable to resolve an Epoch workspace for this account.");
        }
      } catch (error) {
        if (!cancelled) {
          setWorkspaceError(error instanceof Error ? error.message : "Failed to resolve the Epoch workspace.");
        }
      } finally {
        if (!cancelled) {
          setWorkspaceReady(true);
        }
      }
    };

    void bootstrapWorkspace();

    return () => {
      cancelled = true;
    };
  }, []);

  if (!workspaceReady) {
    return (
      <div className="flex min-h-screen items-center justify-center bg-white text-[14px] text-[#555]">
        Loading Mission Control...
      </div>
    );
  }

  return (
    <ContinuityLabProvider>
      {workspaceError ? (
        <div className="flex min-h-screen items-center justify-center bg-white px-6 text-center text-[14px] text-[#555]">
          <div className="max-w-md">
            <div className="font-medium text-[#111]">Mission Control is not ready yet.</div>
            <div className="mt-2">{workspaceError}</div>
          </div>
        </div>
      ) : (
        <MissionControlWorkspace />
      )}
    </ContinuityLabProvider>
  );
}
